extractor:
function extract(frame, memory) {
  memory = memory || {};
  var TICK = 30;
  var PROF = [[0,0],[50,29],[100,53],[150,71],[200,82],[250,88],[300,89],[350,84],[400,73],[450,57],[500,37],[550,12],[600,0]];
  function win(h) {
    var lo = null, hi = null;
    for (var i = 1; i < PROF.length; i++) {
      var a = PROF[i-1], b = PROF[i];
      if (lo === null && a[1] < h && b[1] >= h) lo = a[0] + (h - a[1]) / (b[1] - a[1]) * (b[0] - a[0]);
      if (a[1] >= h && b[1] < h) hi = a[0] + (a[1] - h) / (a[1] - b[1]) * (b[0] - a[0]);
    }
    if (h <= 0) { lo = 0; hi = 600; }
    if (lo === null || hi === null) return null;
    return [lo, hi];
  }
  var P = null, G = null, obs = [], ch = [], over = false;
  for (var i = 0; i < frame.length; i++) {
    var d = frame[i];
    if (d.k === 'text') { if (/game\s*over/i.test(d.t || '')) over = true; continue; }
    if (d.k === 'rect') { if (d.w > 0 && d.h > 0 && d.w < 300 && d.h < 100) obs.push({ kind: 'unknown', x: d.x, y: d.y, w: d.w, h: d.h }); continue; }
    if (d.k !== 'img') continue;
    var m = /:([^,]*),([^,]*),([^,]*),([^,]*)$/.exec(d.s || '');
    var sx = m ? +m[1] : NaN, sy = m ? +m[2] : NaN;
    if (sy >= 50 || d.w >= 300) { if (d.w >= 300 && G === null) G = d.y + d.h + 1; continue; }
    if (d.w === 10 && d.h === 13 && d.y < 40) { ch.push({ x: d.x, c: (sx >= 655 && sx <= 745) ? String((sx - 655) / 10) : sx === 755 ? 'H' : sx === 765 ? 'I' : ' ' }); continue; }
    if (sx >= 645 && sx < 655 && d.w <= 10) continue; // night-mode stars (sky decoration)
    if (sy === 15 && sx >= 655) { over = true; continue; }
    if (sx === 2 && sy === 2) { over = true; continue; }
    if (sx >= 848 && sy <= 2 && d.h >= 20) {
      var st = (sx >= 1112 || d.w > 50) ? 'duck' : sx === 1068 ? 'crashed' : (sx === 936 || sx === 980) ? 'run' : sx === 848 ? 'jump' : sx === 892 ? 'idle' : 'other';
      if (st === 'crashed') over = true;
      P = { x: d.x, y: d.y, w: d.w, h: d.h, state: st };
      continue;
    }
    if (sy === 2 && (sx === 86 || (sx >= 484 && sx < 655))) continue;
    var kind = sy !== 2 ? 'unknown' : (sx >= 228 && sx < 332) ? 'cactus_small' : (sx >= 332 && sx < 484) ? 'cactus_large' : (sx >= 134 && sx < 228) ? 'bird' : 'unknown';
    obs.push({ kind: kind, x: d.x, y: d.y, w: d.w, h: d.h });
  }
  if (G === null) { G = P ? P.y + P.h : 0; for (var j = 0; j < obs.length; j++) G = Math.max(G, obs[j].y + obs[j].h); }
  var pl = P ? P.x : 0, pw = 44, pr = pl + pw;
  var live = obs.filter(function (o) { return o.x + o.w > pl && (o.kind === 'bird' || G - o.y - o.h < 60); }).sort(function (a, b) { return a.x - b.x; });
  // speed tracking (px per ms)
  if (over) { memory.lastX = null; memory.lastKey = null; }
  if (typeof memory.v !== 'number') memory.v = 0.36;
  if (live.length) {
    var f = live[0], key = f.kind + ':' + Math.round(f.w);
    if (memory.lastKey === key && memory.lastX != null) {
      var dl = memory.lastX - f.x;
      if (dl > 2 && dl < 80) { var s = dl / TICK; memory.v = Math.max(0.3, Math.min(1.2, memory.v * 0.6 + s * 0.4)); }
    }
    memory.lastKey = key; memory.lastX = f.x;
  } else { memory.lastKey = null; memory.lastX = null; }
  var v = memory.v;
  var MARGIN = 20;
  var ahead = live.slice(0, 3).map(function (o) {
    var bottom = Math.round(G - o.y - o.h), top = Math.round(G - o.y);
    var dx = Math.round(o.x - pr);
    var entry = (dx + 6) / v, exit = (dx + 6 + o.w + pw - 12) / v;
    var overhead = o.kind === 'bird' && bottom >= 45;
    var duckable = o.kind === 'bird' && !overhead && bottom >= 25;
    var timing = 'late';
    var w = win(Math.max(0, top - 6));
    if (w) {
      var slackLate = entry - (w[0] + MARGIN);
      var slackEarly = (w[1] - MARGIN) - exit;
      timing = slackEarly < slackLate ? 'early' : (slackLate >= 0 && slackEarly >= 0 ? 'ok' : 'late');
    }
    return { kind: o.kind, dx: dx, w: Math.round(o.w), top: top, bottom: bottom, impactMs: Math.round(entry), passMs: Math.round(exit), overhead: overhead, duckable: duckable, jumpTiming: timing };
  });
  var threat = null;
  for (var q = 0; q < ahead.length; q++) { if (!ahead[q].overhead) { threat = ahead[q]; break; } }
  ch.sort(function (a, b) { return a.x - b.x; });
  var runs = [], cur = null, lx = -1e9;
  for (var k = 0; k < ch.length; k++) { if (cur === null || ch[k].x - lx > 12) { cur = runs.length; runs.push(''); } runs[cur] += ch[k].c; lx = ch[k].x; }
  var score = null, hi = null;
  for (var r = 0; r < runs.length; r++) {
    var digits = runs[r].replace(/\D/g, '');
    if (!digits) continue;
    if (/^HI/.test(runs[r])) hi = parseInt(digits, 10); else score = parseInt(digits, 10);
  }
  var alt = P ? Math.round(G - P.y - P.h) : 0;
  return {
    over: over,
    player: P ? { alt: alt, air: alt > 1 || P.state === 'jump', state: P.state } : null,
    speedPxPerMs: Math.round(v * 1000) / 1000,
    score: score,
    hi: hi,
    threat: threat,
    obstacles: ahead
  };
}

teacher:
function teach(state) {
  if (!state) return 'NOOP';
  // 1. Game over -> JUMP restarts
  if (state.over === true) return 'JUMP';
  // 2. In the air -> NOOP (release keys so the next jump is a fresh press)
  if (state.player && state.player.air === true) return 'NOOP';
  var t = state.threat;
  // 3. No threat -> NOOP
  if (t === null || t === undefined) return 'NOOP';
  // 4. Duckable bird close enough (or already passing) -> DUCK
  if (t.duckable === true && typeof t.impactMs === 'number' && t.impactMs <= 250) return 'DUCK';
  // 5. Jump timing ok or late -> JUMP
  if (t.jumpTiming === 'ok' || t.jumpTiming === 'late') return 'JUMP';
  // 6. Otherwise (early) -> wait
  return 'NOOP';
}
